for line in a.splitlines():
    m=re.match(r'\| (Q\d+) \| `spec/requirement.md:(\d+)`[^|]*\| (.*) \|$',line)
    if m:
        q,n,s=m.groups();quote_checks.append({'id':q,'source_line':int(n),'exact':s==req[int(n)-1]})
counts={k:len(set(re.findall(r'^\| ('+k+r'\d+)\b',a,re.M))) for k in ['A','D','B','U']}
errors=[]
for prefix,start,end in [('A','### 4.1','### 4.2'),('D','### 5.1','## 6.')]:
    section=a.split(start,1)[1].split(end,1)[0]
    rows=[x for x in section.splitlines() if re.match(r'^\| '+prefix+r'\d+ \|',x)]
    for row in rows:
        cells=[x.strip() for x in row.strip().strip('|').split('|')]
        if len(cells)!=9 or not all(cells): errors.append({'kind':'eight_dimensions','id':cells[0],'count':len(cells)})
for row in a.splitlines():
    if re.match(r'^\| B\d+ ',row):
        for label in ['入口：','前置数据：','用户动作：','UI结果：','数据结果：','网络结果：','返回结果：','边界条件：']:
            if label not in row: errors.append({'kind':'boundary_dimension','id':row.split('|')[1].split()[0],'missing':label})
link_count=0
for docname,doc in [('acceptance.md',a),('baseline-notes.md',b)]:
    for target in re.findall(r'\[[^\]]+\]\(([^)]+)\)',doc):
        if '://' in target or target.startswith('#'):continue
        link_count+=1
        match=re.match(r'^(.*?)(?::(\d+))?$',target)
        name,line=match.groups();file=(p/'spec'/name).resolve()
        if not file.is_file():errors.append({'kind':'missing_link','doc':docname,'target':target});continue
        if line and file.suffix.lower() not in ['.png','.hap']:
            n=len(file.read_text(encoding='utf-8-sig',errors='replace').splitlines())
            if int(line)>n:errors.append({'kind':'link_line_out_of_range','doc':docname,'target':target,'lines':n})
manifest=json.loads((p/'workflow/analysis-start-code-fingerprint.json').read_text(encoding='utf-8'))
changed=[f for f,h in manifest['tracked_files_sha256'].items() if not (p/f).is_file() or hashlib.sha256((p/f).read_bytes()).hexdigest()!=h]
head=subprocess.check_output(['git','rev-parse','HEAD'],cwd=p).decode().strip()
log=p/'logs/baseline-20261016/build-raw.log'
warning_summary=json.loads((p/'logs/baseline-20261016/warnings-summary.json').read_text(encoding='utf-8-sig'))
warning_hash_matches=hashlib.sha256(log.read_bytes()).hexdigest()==warning_summary['build_log_sha256']
hap=p/'entry/build/default/outputs/default/entry-default-unsigned.hap'
hap_hash=hashlib.sha256(hap.read_bytes()).hexdigest()
result={'checked_at':datetime.now(timezone.utc).isoformat(),'scope':'analysis-only document QA; no production tests or edits','spec_quotes':quote_checks,'all_15_quotes_exact':len(quote_checks)==15 and all(x['exact'] for x in quote_checks),'matrix_counts':counts,'document_links_checked':link_count,'document_errors':errors,'tracked_files_checked':len(manifest['tracked_files_sha256']),'tracked_changes_since_start':changed,'head':head,'warning_log_hash_matches':warning_hash_matches,'hap_hash_in_baseline_document':hap_hash in b,'artifact_hashes':{name:hashlib.sha256((p/name).read_bytes()).hexdigest() for name in ['spec/acceptance.md','spec/baseline-notes.md']}}
result['pass']=result['all_15_quotes_exact'] and counts=={'A':16,'D':7,'B':28,'U':10} and not errors and not changed and head==manifest['head'] and warning_hash_matches and result['hap_hash_in_baseline_document']
out=p/'logs/analysis-document-qa.json';out.write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(json.dumps(result,ensure_ascii=False))
